import React from 'react';
import { View } from 'react-native';

import { Cards } from '../../components/Cards';
import { styles } from './styles';

interface ListItemProps {
    data: {
        firstCard: number,
        id: string
    };
    list?: {
        [key: string]: [{
            id: number;
            name: string;
            phone: string;
            price: number;
            analyzed: number
        }]
    };
};

export function ListItem(listItemProps: ListItemProps) {

    const {ButtonCard} = Cards()

    return (
        <View style={styles.listItem}>
            <ButtonCard {...{ listItemProps }} position={0} />
            <ButtonCard {...{ listItemProps }} position={1} />
            <ButtonCard {...{ listItemProps }} position={2} />
            <ButtonCard {...{ listItemProps }} position={3} />
            <ButtonCard {...{ listItemProps }} position={4} />
            <ButtonCard {...{ listItemProps }} position={5} />
        </View>
    );
};
